   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这个人，你们的链尉官，他每一次站在最前面，不是因为这样做能带来什么，也不是因为这样做就有人能记住他。", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_13_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而是这通常意味着后面已经无路可退，他必须保护所有人。", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_13_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而只要他往前走一步，数不清的敌人、污染、甚至还有使徒级的修格尔就会冲着他而来。", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_13_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
